def parse_row(line):
    parts = line.split(",")
    name = parts[0]
    value = int(parts[1])
    return name, value

def load(path):
    result = {}
    with open(path) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            key, value = parse_row(line)
            result[key] = value
    return result
